{"path": "/home/daytona/inspect_sandbox.py", "content": "from daytona import Daytona, DaytonaConfig

config = DaytonaConfig(
    api_url="https://app.daytona.io/api",
)
daytona = Daytona(config)

sandbox = daytona.create()
print(f"Sandbox created: {sandbox.id}")
print(f"Sandbox state: {sandbox.state}")

# Inspect all attributes
print("\n--- Sandbox attributes ---")
for attr in sorted(dir(sandbox)):
    if not attr.startswith('_'):
        try:
            val = getattr(sandbox, attr)
            if not callable(val):
                print(f"  {attr}: {val}")
        except:
            pass

print("\n--- Additional properties ---")
print(sandbox.additional_properties)
"}
